import itertools
from fractions import Fraction as F
# rectangle width 2 height 4; lines as segments
segs=[((0,0),(2,0)),((0,2),(2,2)),((0,4),(2,4)),((0,0),(0,4)),((1,0),(1,4)),((2,0),(2,4)),((0,0),(2,4))]
pts=set()
for s in segs: pts|={s[0],s[1]}
def inter(s,t):
    (x1,y1),(x2,y2)=s;(x3,y3),(x4,y4)=t
    d=(x1-x2)*(y3-y4)-(y1-y2)*(x3-x4)
    if d==0: return None
    u=F((x1-x3)*(y3-y4)-(y1-y3)*(x3-x4),d); w=F((x1-x3)*(y1-y2)-(y1-y3)*(x1-x2),d)
    if 0<=u<=1 and 0<=w<=1: return (x1+u*(x2-x1),y1+u*(y2-y1))
for s,t in itertools.combinations(segs,2):
    p=inter(s,t)
    if p: pts.add(p)
pts=[(F(x),F(y)) for x,y in pts]
def onseg(p,q):
    for (a,b) in segs:
        a=(F(a[0]),F(a[1]));b=(F(b[0]),F(b[1]))
        def col(r): return (b[0]-a[0])*(r[1]-a[1])-(b[1]-a[1])*(r[0]-a[0])==0
        def within(r): return min(a[0],b[0])<=r[0]<=max(a[0],b[0]) and min(a[1],b[1])<=r[1]<=max(a[1],b[1])
        if col(p) and col(q) and within(p) and within(q): return True
    return False
n=0
for a,b,c in itertools.combinations(pts,3):
    if (b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0])==0: continue
    if onseg(a,b) and onseg(b,c) and onseg(a,c): n+=1
opts={"A":6,"B":2,"C":4,"D":7}
assert n==opts["A"] and all(n!=opts[k] for k in "BCD")

